style.css:
@-moz-document domain("roblox.com") {
html, body {
    min-height: 100vh !important;
    background-image: url("data:image/jpeg;base64,AAA...tuimagen...") !important;
    background-size: cover !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
  }

  /* Forzar transparencia en los contenedores principales */
  .container, .game-card, .page-container, .rbx-body, .content {
    background: transparent !important;
    box-shadow: none !important;
  }

  /* Ajustar modales y navbar para que no bloqueen el fondo */
  .modal, .modal-backdrop {
    background: rgba(0,0,0,0.6) !important;
  }

  .navbar, .top-navbar {
    background: rgba(255,255,255,0.85) !important;
  }
}
